{
  "background_need": "Three rural communities in the Fictional Reedshore region face seasonal visitor demand and sensitive wetland habitats. Two tourism firms propose an eighteen-month low-impact route pilot to support local services, but no ecological baseline or visitor survey data exists.",
  "objectives": [
    {
      "id": "O1",
      "description": "Establish accessible off-season routes that maintain habitat integrity while supporting local services."
    },
    {
      "id": "O2",
      "description": "Enable tourism firms and community volunteers to safely manage visitor flow without increasing pressure on wetland habitats."
    }
  ],
  "target_groups": [
    "Fictional small tourism firms",
    "Fictional community volunteers"
  ],
  "preliminary_activities": [
    {
      "id": "A1",
      "description": "Conduct a preliminary habitat sensitivity assessment to identify high-risk zones for the proposed routes.",
      "objective_ids": ["O1"]
    },
    {
      "id": "A2",
      "description": "Co-design route specifications with tourism firms and volunteers, incorporating low-impact principles.",
      "objective_ids": ["O1", "O2"]
    }
  ],
  "expected_results": [
    {
      "id": "R1",
      "description": "Completion of habitat sensitivity assessment identifying at least two high-risk zones.",
      "activity_ids": ["A1"]
    },
    {
      "id": "R2",
      "description": "Finalisation of route specifications agreed upon by all target groups.",
      "activity_ids": ["A2"]
    }
  ],
  "proposed_indicators": [
    {
      "id": "I1",
      "description": "Number of high-risk habitat zones identified during preliminary assessment.",
      "result_ids": ["R1"],
      "measurement_method": "Field survey by designated volunteers using standard ecological risk criteria."
    },
    {
      "id": "I2",
      "description": "Percentage of target group members who co-design the route specifications (target: 100%).",
      "result_ids": ["R2"],
      "measurement_method": "Survey of participation records from tourism firms and volunteers."
    }
  ],
  "assumptions": [
    "Volunteers possess sufficient ecological training to conduct preliminary habitat assessments.",
    "Tourism firms have the capacity to commit resources for co-design workshops within an eighteen-month timeframe.",
    "No existing protected status prevents route modifications in identified high-risk zones."
  ]
}
